 *
 * shape ActionableOverdue = OverdueInvoice and not ArchivedInvoice
 *
 * rule RemindOverdue when (ActionableOverdue where not (exists (Reminder where (invoice == this) and (sentOn > (today - 7 days))))) on Weekly {
 *     Reminder from { invoice: this, sentOn: today }
 * }
 *
 */
class OverdueInvoiceSpec : SpecSupport() {

    @Test
    fun `RemindOverdue - the Weekly sweep serves ActionableOverdue`() {
        val beforeReminder = count("Reminder")
        val invoice = givens.populateRemindOverdue()
        assertTrue(member(invoice, "ActionableOverdue"), "the given must deliver a member of 'ActionableOverdue'")
        sys.system.tick("Weekly")
